from decimal import Decimal
from typing import Any


class BusinessRuleViolation(Exception):
    code: str
    message: str

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric coercion, where an empty string is numeric zero."""
    if value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _lookup_role(user_id: str, users: list[dict]) -> str:
    """Implement legacy LOOKUP against the first live matching row."""
    for user in users:
        if user.get("DEL_FLG", "") != "Y" and user.get("USR_ID") == user_id:
            return user.get("ROLE_ID", "")
    return ""


def set_discount(order: dict, pct, user_id: str, users: list[dict]) -> dict:
    """Validate and return a copy of an order with its discount updated."""
    discount = _numeric(pct)

    # ORD-001: range validation runs first.
    if not (Decimal("0") <= discount <= Decimal("100")):
        raise BusinessRuleViolation("E5001", "Discount out of range")

    # ORD-002: discounts over 20 require a manager role.
    if discount > Decimal("20"):
        role = _lookup_role(user_id, users)
        if role not in ("MGR", "ADMIN"):
            raise BusinessRuleViolation(
                "E5002",
                "Discount over 20 percent requires manager role",
            )

    updated_order = dict(order)
    updated_order["DISC_PCT"] = pct
    return updated_order
